#!/usr/bin/env node
// Regenerates src/esi/regionData.json from CCP's official Static Data Export (SDE).
//
// Regions rarely change, so instead of relying on the ESI universe endpoints (which would
// require a request per region to resolve names), Evelyn bundles a trimmed dataset generated by
// this script. This is the same approach used for src/esi/npcCorporationData.json and
// src/esi/blueprintData.json.
//
// This script is run automatically by `yarn generate-data` and by CI before packaging the
// app. It can also be run manually to update the bundled data:
//
//   node scripts/generate-region-data.mjs
//
// It requires network access to developers.eveonline.com.
//
// Docs: https://developers.eveonline.com/docs/services/static-data/

import { writeFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import { downloadSdeZip, extractYamlFile, isMainModule } from "./sde.mjs";

const OUTPUT_PATH = fileURLToPath(new URL("../src/esi/regionData.json", import.meta.url));

// Wormhole ("J-space") regions are named like "A-R00001" and don't have NPC stations or markets,
// so they're excluded from the bundled dataset since they'd be useless (and confusing) choices
// for a price-check region selector.
const WORMHOLE_REGION_NAME = /^[A-Z]-R\d+$/;

export async function generate(zipBuffer) {
  // CCP dropped the `fsd/` directory prefix in a later SDE rework, so the current layout has
  // this file at the zip root; the prefixed path is kept as a fallback for older zips.
  const regions = extractYamlFile(zipBuffer, ["mapRegions.yaml", "fsd/mapRegions.yaml"]);

  const data = [];
  for (const [regionIdStr, region] of Object.entries(regions)) {
    if (region.deleted) continue;

    const name = region.name?.en;
    if (!name) continue;
    if (WORMHOLE_REGION_NAME.test(name)) continue;

    data.push({ regionId: Number(regionIdStr), name });
  }

  data.sort((a, b) => a.name.localeCompare(b.name));
  await writeFile(OUTPUT_PATH, JSON.stringify(data));

  console.log(`Wrote ${data.length} regions to ${OUTPUT_PATH}`);
}

async function main() {
  await generate(await downloadSdeZip());
}

if (isMainModule(import.meta.url)) {
  main().catch((err) => {
    console.error(err);
    process.exitCode = 1;
  });
}
